        for (x=0; x < (ssize_t) picon->columns; x++)
        {
          if (GetPixelAlpha(picon,q) == (Quantum) TransparentAlpha)
            SetPixelIndex(picon,(Quantum) picon->colors,q);
          q+=GetPixelChannels(picon);
